// TestStreamingSignerStub checks the methods, the constructors and the
// options of the double StreamingSignerStub.
func TestStreamingSignerStub(t *testing.T) {
	t.Parallel()

	t.Run("NewSignStream", func(t *testing.T) {
		t.Parallel()
		stub.Behaviour(t, "NewSignStream", streamingSignerStubNewSignStreamSubject)
	})

	t.Run("Sign", func(t *testing.T) {
		t.Parallel()
		stub.Behaviour(t, "Sign", streamingSignerStubSignSubject)
	})

	t.Run("KeyID", func(t *testing.T) {
		t.Parallel()
		stub.Behaviour(t, "KeyID", streamingSignerStubKeyIDSubject)
	})

	t.Run("PublicKey", func(t *testing.T) {
		t.Parallel()
		stub.Behaviour(t, "PublicKey", streamingSignerStubPublicKeySubject)
	})

	t.Run("Algorithm", func(t *testing.T) {
		t.Parallel()
		stub.Behaviour(t, "Algorithm", streamingSignerStubAlgorithmSubject)
	})

	t.Run("Verify", func(t *testing.T) {
		t.Parallel()
		stub.Behaviour(t, "Verify", streamingSignerStubVerifySubject)
	})

	t.Run("ResetCalls", func(t *testing.T) {
		t.Parallel()

		t.Run("NewSignStream", func(t *testing.T) {
			t.Parallel()
			stub.ResetBehaviour(t, "NewSignStream", streamingSignerStubNewSignStreamSubject)
		})

		t.Run("Sign", func(t *testing.T) {
			t.Parallel()
			stub.ResetBehaviour(t, "Sign", streamingSignerStubSignSubject)
		})

		t.Run("KeyID", func(t *testing.T) {
			t.Parallel()
			stub.ResetBehaviour(t, "KeyID", streamingSignerStubKeyIDSubject)
		})

		t.Run("PublicKey", func(t *testing.T) {
			t.Parallel()
			stub.ResetBehaviour(t, "PublicKey", streamingSignerStubPublicKeySubject)
		})

		t.Run("Algorithm", func(t *testing.T) {
			t.Parallel()
			stub.ResetBehaviour(t, "Algorithm", streamingSignerStubAlgorithmSubject)
		})

		t.Run("Verify", func(t *testing.T) {
			t.Parallel()
			stub.ResetBehaviour(t, "Verify", streamingSignerStubVerifySubject)
		})
	})

	t.Run("StreamingSignerStubStrict", func(t *testing.T) {
		t.Parallel()
		stub.StrictBehaviour(t, func(tb assert.TB) streamingSignerStubInstance {
			return streamingSignerStubInstanceOf(
				tb,
				cryptotest.NewStreamingSignerStub(tb, cryptotest.StreamingSignerStubStrict()),
			)
		})
	})

	t.Run("StreamingSignerStubDelegateTo", func(t *testing.T) {
		t.Parallel()

		t.Run("passes NewSignStream to the implementation", func(t *testing.T) {
			t.Parallel()
			inner := cryptotest.NewStreamingSignerStub(t)
			s := cryptotest.NewStreamingSignerStub(t, cryptotest.StreamingSignerStubDelegateTo(inner))
			_ = streamingSignerStubNewSignStream(t, s)
			inner.OnNewSignStream.AssertCalledOnce(t, "NewSignStream calls the implementation")
		})

		t.Run("passes Sign to the implementation", func(t *testing.T) {
			t.Parallel()
			inner := cryptotest.NewStreamingSignerStub(t)
			s := cryptotest.NewStreamingSignerStub(t, cryptotest.StreamingSignerStubDelegateTo(inner))
			_, _ = streamingSignerStubSign(t, s)
			inner.OnSign.AssertCalledOnce(t, "Sign calls the implementation")
		})

		t.Run("fails Sign with the error of the implementation", func(t *testing.T) {
			t.Parallel()
			want := errors.New("Sign-delegate")
			inner := cryptotest.NewStreamingSignerStub(t)
			inner.OnSign.Faults(want, 1)
			s := cryptotest.NewStreamingSignerStub(t, cryptotest.StreamingSignerStubDelegateTo(inner))
			_, r1 := streamingSignerStubSign(t, s)
			assert.ErrorIs(t, r1, want, "Sign fails with the error of the implementation")
		})

		t.Run("passes KeyID to the implementation", func(t *testing.T) {
			t.Parallel()
			inner := cryptotest.NewStreamingSignerStub(t)
			s := cryptotest.NewStreamingSignerStub(t, cryptotest.StreamingSignerStubDelegateTo(inner))
			_ = streamingSignerStubKeyID(t, s)
			inner.OnKeyID.AssertCalledOnce(t, "KeyID calls the implementation")
		})

		t.Run("passes PublicKey to the implementation", func(t *testing.T) {
			t.Parallel()
			inner := cryptotest.NewStreamingSignerStub(t)
			s := cryptotest.NewStreamingSignerStub(t, cryptotest.StreamingSignerStubDelegateTo(inner))
			_ = streamingSignerStubPublicKey(t, s)
			inner.OnPublicKey.AssertCalledOnce(t, "PublicKey calls the implementation")
		})

		t.Run("passes Algorithm to the implementation", func(t *testing.T) {
			t.Parallel()
			inner := cryptotest.NewStreamingSignerStub(t)
			s := cryptotest.NewStreamingSignerStub(t, cryptotest.StreamingSignerStubDelegateTo(inner))
			_ = streamingSignerStubAlgorithm(t, s)
			inner.OnAlgorithm.AssertCalledOnce(t, "Algorithm calls the implementation")
		})

		t.Run("passes Verify to the implementation", func(t *testing.T) {
			t.Parallel()
			inner := cryptotest.NewStreamingSignerStub(t)
			s := cryptotest.NewStreamingSignerStub(t, cryptotest.StreamingSignerStubDelegateTo(inner))
			_ = streamingSignerStubVerify(t, s)
			inner.OnVerify.AssertCalledOnce(t, "Verify calls the implementation")
		})
	})

	t.Run("StreamingSignerStubWithClock", func(t *testing.T) {
		t.Parallel()
		stub.ClockBehaviour(t, func(tb assert.TB, clk assert.Clock) streamingSignerStubInstance {
			return streamingSignerStubInstanceOf(
				tb,
				cryptotest.NewStreamingSignerStub(tb, cryptotest.StreamingSignerStubWithClock(clk)),
			)
		})
	})

	t.Run("StreamingSignerStubWithRandSource", func(t *testing.T) {
		t.Parallel()
		stub.RandSourceBehaviour(t, func(tb assert.TB, src rand.Source) streamingSignerStubInstance {
			return streamingSignerStubInstanceOf(
				tb,
				cryptotest.NewStreamingSignerStub(tb, cryptotest.StreamingSignerStubWithRandSource(src)),
			)
		})
	})

	t.Run("StreamingSignerStubBenchMode", func(t *testing.T) {
		t.Parallel()
		stub.BenchModeBehaviour(t, func(tb assert.TB) streamingSignerStubInstance {
			return streamingSignerStubInstanceOf(
				tb,
				cryptotest.NewStreamingSignerStub(tb, cryptotest.StreamingSignerStubBenchMode()),
			)
		})
	})

	t.Run("StreamingSignerStubWithLatency", func(t *testing.T) {
		t.Parallel()
		stub.LatencyBehaviour(t, func(tb assert.TB, d time.Duration, clk assert.Clock) streamingSignerStubInstance {
			return streamingSignerStubInstanceOf(
				tb,
				cryptotest.NewStreamingSignerStub(
					tb,
					cryptotest.StreamingSignerStubWithClock(clk),
					cryptotest.StreamingSignerStubWithLatency(d),
				),
			)
		})
	})

	t.Run("StreamingSignerStubFailing", func(t *testing.T) {
		t.Parallel()

		t.Run("fails Sign with its error", func(t *testing.T) {
			t.Parallel()
			want := errors.New("Sign-failing")
			s := cryptotest.NewStreamingSignerStub(t, cryptotest.StreamingSignerStubFailing(want))
			_, r1 := streamingSignerStubSign(t, s)
			assert.ErrorIs(t, r1, want, "Sign fails with the error of StreamingSignerStubFailing")
		})
	})

	t.Run("WithStreamingSignerNewSignStream", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the function of NewSignStream", func(t *testing.T) {
			t.Parallel()
			called := false
			s := cryptotest.NewStreamingSignerStub(
				t,
				cryptotest.WithStreamingSignerNewSignStream(func() sign.SignStream {
					called = true
					var z0 sign.SignStream
					return z0
				}),
			)
			_ = streamingSignerStubNewSignStream(t, s)
			assert.True(t, called, "WithStreamingSignerNewSignStream sets the function of NewSignStream")
		})
	})

	t.Run("WithStreamingSignerSign", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the function of Sign", func(t *testing.T) {
			t.Parallel()
			called := false
			s := cryptotest.NewStreamingSignerStub(
				t,
				cryptotest.WithStreamingSignerSign(func(_ []byte) ([]byte, error) {
					called = true
					var z0 []byte
					var z1 error
					return z0, z1
				}),
			)
			_, _ = streamingSignerStubSign(t, s)
			assert.True(t, called, "WithStreamingSignerSign sets the function of Sign")
		})
	})

	t.Run("WithStreamingSignerKeyID", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the function of KeyID", func(t *testing.T) {
			t.Parallel()
			called := false
			s := cryptotest.NewStreamingSignerStub(t, cryptotest.WithStreamingSignerKeyID(func() sign.KeyID {
				called = true
				var z0 sign.KeyID
				return z0
			}))
			_ = streamingSignerStubKeyID(t, s)
			assert.True(t, called, "WithStreamingSignerKeyID sets the function of KeyID")
		})
	})

	t.Run("WithStreamingSignerPublicKey", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the function of PublicKey", func(t *testing.T) {
			t.Parallel()
			called := false
			s := cryptotest.NewStreamingSignerStub(t, cryptotest.WithStreamingSignerPublicKey(func() []byte {
				called = true
				var z0 []byte
				return z0
			}))
			_ = streamingSignerStubPublicKey(t, s)
			assert.True(t, called, "WithStreamingSignerPublicKey sets the function of PublicKey")
		})
	})

	t.Run("WithStreamingSignerAlgorithm", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the function of Algorithm", func(t *testing.T) {
			t.Parallel()
			called := false
			s := cryptotest.NewStreamingSignerStub(t, cryptotest.WithStreamingSignerAlgorithm(func() crypto.Algorithm {
				called = true
				var z0 crypto.Algorithm
				return z0
			}))
			_ = streamingSignerStubAlgorithm(t, s)
			assert.True(t, called, "WithStreamingSignerAlgorithm sets the function of Algorithm")
		})
	})

	t.Run("WithStreamingSignerVerify", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the function of Verify", func(t *testing.T) {
			t.Parallel()
			called := false
			s := cryptotest.NewStreamingSignerStub(t, cryptotest.WithStreamingSignerVerify(func(_, _ []byte) bool {
				called = true
				var z0 bool
				return z0
			}))
			_ = streamingSignerStubVerify(t, s)
			assert.True(t, called, "WithStreamingSignerVerify sets the function of Verify")
		})
	})
}

// signStreamStubSignAndReset calls SignAndReset of s with the samples of
// its arguments.
func signStreamStubSignAndReset(tb assert.TB, s *cryptotest.SignStreamStub) ([]byte, error) {
	tb.Helper()
	return s.SignAndReset()
}

// signStreamStubSignAndResetPins returns the samples of the results of
// SignAndReset, with a new error as its error result.
func signStreamStubSignAndResetPins() ([]byte, error) {
	var want0 []byte
	want1 := errors.New("SignAndReset-returns")
	want0 = []byte{1}
	return want0, want1
}

// signStreamStubWriteArgs returns the samples of the arguments of Write.
func signStreamStubWriteArgs(tb assert.TB) []byte {
	tb.Helper()
	var a0 []byte
	a0 = []byte{1}
	return a0
}

// signStreamStubWrite calls Write of s with the samples of its arguments.
func signStreamStubWrite(tb assert.TB, s *cryptotest.SignStreamStub) (int, error) {
	tb.Helper()
	a0 := signStreamStubWriteArgs(tb)
	return s.Write(a0)
}

// signStreamStubWritePins returns the samples of the results of Write,
// with a new error as its error result.
func signStreamStubWritePins() (int, error) {
	var want0 int
	want1 := errors.New("Write-returns")
	want0 = 42
	return want0, want1
}

// signStreamStubSignAndResetSubject returns the subject of
// [stub.Behaviour] and [stub.ResetBehaviour] for SignAndReset. The subject
// calls a new double that reports to tb.
func signStreamStubSignAndResetSubject(
	tb assert.TB,
) stub.Subject[cryptotest.SignStreamSignAndResetCall, cryptotest.SignStreamSignAndResetReturn] {
	tb.Helper()
	s := cryptotest.NewSignStreamStub(tb)
	return stub.Subject[cryptotest.SignStreamSignAndResetCall, cryptotest.SignStreamSignAndResetReturn]{
		Stub:  s.OnSignAndReset.MethodStub,
		Reset: s.ResetCalls,
		Call: func() {
			_, _ = signStreamStubSignAndReset(tb, s)
		},
		Result: func() cryptotest.SignStreamSignAndResetReturn {
			got0, got1 := signStreamStubSignAndReset(tb, s)
			return cryptotest.SignStreamSignAndResetReturn{Result: got0, Err: got1}
		},
		Returns: func() cryptotest.SignStreamSignAndResetReturn {
			want0, want1 := signStreamStubSignAndResetPins()
			s.OnSignAndReset.Returns(want0, want1)
			return cryptotest.SignStreamSignAndResetReturn{Result: want0, Err: want1}
		},
		Override: func(seen func(cryptotest.SignStreamSignAndResetCall)) {
			s.OnSignAndReset.Func(func() ([]byte, error) {
				seen(cryptotest.SignStreamSignAndResetCall{})
				var z0 []byte
				var z1 error
				return z0, z1
			})
		},
		Fails: func() error {
			_, r1 := signStreamStubSignAndReset(tb, s)
			return r1
		},
	}
}

// signStreamStubWriteSubject returns the subject of [stub.Behaviour] and
// [stub.ResetBehaviour] for Write. The subject calls a new double that
// reports to tb.
func signStreamStubWriteSubject(
	tb assert.TB,
) stub.Subject[cryptotest.SignStreamWriteCall, cryptotest.SignStreamWriteReturn] {
	tb.Helper()
	s := cryptotest.NewSignStreamStub(tb)
	return stub.Subject[cryptotest.SignStreamWriteCall, cryptotest.SignStreamWriteReturn]{
		Stub:  s.OnWrite.MethodStub,
		Reset: s.ResetCalls,
		Call: func() {
			_, _ = signStreamStubWrite(tb, s)
		},
		Arguments: func(tb assert.TB, c cryptotest.SignStreamWriteCall) {
			tb.Helper()
			a0 := signStreamStubWriteArgs(tb)
			assert.Equal(tb, c.P, a0, "the call records P")
		},
		Result: func() cryptotest.SignStreamWriteReturn {
			got0, got1 := signStreamStubWrite(tb, s)
			return cryptotest.SignStreamWriteReturn{N: got0, Err: got1}
		},
		Returns: func() cryptotest.SignStreamWriteReturn {
			want0, want1 := signStreamStubWritePins()
			s.OnWrite.Returns(want0, want1)
			return cryptotest.SignStreamWriteReturn{N: want0, Err: want1}
		},
		Override: func(seen func(cryptotest.SignStreamWriteCall)) {
			s.OnWrite.Func(func(p0 []byte) (int, error) {
				seen(cryptotest.SignStreamWriteCall{P: p0})
				var z0 int
				var z1 error
				return z0, z1
			})
		},
		Fails: func() error {
			_, err := signStreamStubWrite(tb, s)
			return err
		},
	}
}

// signStreamStubInstance is the instance of a cryptotest.SignStreamStub
// that the checks of the constructors and the options drive.
type signStreamStubInstance = stub.Instance[cryptotest.SignStreamSignAndResetCall]

// signStreamStubInstanceOf returns the instance of s. The options apply to
// the whole double, so the checks call SignAndReset alone.
func signStreamStubInstanceOf(tb assert.TB, s *cryptotest.SignStreamStub) signStreamStubInstance {
	tb.Helper()
	return signStreamStubInstance{
		Stub: s.OnSignAndReset.MethodStub,
		Call: func() {
			_, _ = signStreamStubSignAndReset(tb, s)
		},
	}
}

// TestSignStreamStub checks the methods, the constructors and the options
// of the double SignStreamStub.
func TestSignStreamStub(t *testing.T) {
	t.Parallel()

	t.Run("SignAndReset", func(t *testing.T) {
		t.Parallel()
		stub.Behaviour(t, "SignAndReset", signStreamStubSignAndResetSubject)
	})

	t.Run("Write", func(t *testing.T) {
		t.Parallel()
		stub.Behaviour(t, "Write", signStreamStubWriteSubject)
	})

	t.Run("ResetCalls", func(t *testing.T) {
		t.Parallel()

		t.Run("SignAndReset", func(t *testing.T) {
			t.Parallel()
			stub.ResetBehaviour(t, "SignAndReset", signStreamStubSignAndResetSubject)
		})

		t.Run("Write", func(t *testing.T) {
			t.Parallel()
			stub.ResetBehaviour(t, "Write", signStreamStubWriteSubject)
		})
	})

	t.Run("SignStreamStubStrict", func(t *testing.T) {
		t.Parallel()
		stub.StrictBehaviour(t, func(tb assert.TB) signStreamStubInstance {
			return signStreamStubInstanceOf(tb, cryptotest.NewSignStreamStub(tb, cryptotest.SignStreamStubStrict()))
		})
	})

	t.Run("SignStreamStubDelegateTo", func(t *testing.T) {
		t.Parallel()

		t.Run("passes SignAndReset to the implementation", func(t *testing.T) {
			t.Parallel()
			inner := cryptotest.NewSignStreamStub(t)
			s := cryptotest.NewSignStreamStub(t, cryptotest.SignStreamStubDelegateTo(inner))
			_, _ = signStreamStubSignAndReset(t, s)
			inner.OnSignAndReset.AssertCalledOnce(t, "SignAndReset calls the implementation")
		})

		t.Run("fails SignAndReset with the error of the implementation", func(t *testing.T) {
			t.Parallel()
			want := errors.New("SignAndReset-delegate")
			inner := cryptotest.NewSignStreamStub(t)
			inner.OnSignAndReset.Faults(want, 1)
			s := cryptotest.NewSignStreamStub(t, cryptotest.SignStreamStubDelegateTo(inner))
			_, r1 := signStreamStubSignAndReset(t, s)
			assert.ErrorIs(t, r1, want, "SignAndReset fails with the error of the implementation")
		})

		t.Run("passes Write to the implementation", func(t *testing.T) {
			t.Parallel()
			inner := cryptotest.NewSignStreamStub(t)
			s := cryptotest.NewSignStreamStub(t, cryptotest.SignStreamStubDelegateTo(inner))
			_, _ = signStreamStubWrite(t, s)
			inner.OnWrite.AssertCalledOnce(t, "Write calls the implementation")
		})

		t.Run("fails Write with the error of the implementation", func(t *testing.T) {
			t.Parallel()
			want := errors.New("Write-delegate")
			inner := cryptotest.NewSignStreamStub(t)
			inner.OnWrite.Faults(want, 1)
			s := cryptotest.NewSignStreamStub(t, cryptotest.SignStreamStubDelegateTo(inner))
			_, err := signStreamStubWrite(t, s)
			assert.ErrorIs(t, err, want, "Write fails with the error of the implementation")
		})
	})

	t.Run("SignStreamStubWithClock", func(t *testing.T) {
		t.Parallel()
		stub.ClockBehaviour(t, func(tb assert.TB, clk assert.Clock) signStreamStubInstance {
			return signStreamStubInstanceOf(
				tb,
				cryptotest.NewSignStreamStub(tb, cryptotest.SignStreamStubWithClock(clk)),
			)
		})
	})

	t.Run("SignStreamStubWithRandSource", func(t *testing.T) {
		t.Parallel()
		stub.RandSourceBehaviour(t, func(tb assert.TB, src rand.Source) signStreamStubInstance {
			return signStreamStubInstanceOf(
				tb,
				cryptotest.NewSignStreamStub(tb, cryptotest.SignStreamStubWithRandSource(src)),
			)
		})
	})

	t.Run("SignStreamStubBenchMode", func(t *testing.T) {
		t.Parallel()
		stub.BenchModeBehaviour(t, func(tb assert.TB) signStreamStubInstance {
			return signStreamStubInstanceOf(tb, cryptotest.NewSignStreamStub(tb, cryptotest.SignStreamStubBenchMode()))
		})
	})

	t.Run("SignStreamStubWithLatency", func(t *testing.T) {
		t.Parallel()
		stub.LatencyBehaviour(t, func(tb assert.TB, d time.Duration, clk assert.Clock) signStreamStubInstance {
			return signStreamStubInstanceOf(
				tb,
				cryptotest.NewSignStreamStub(
					tb,
					cryptotest.SignStreamStubWithClock(clk),
					cryptotest.SignStreamStubWithLatency(d),
				),
			)
		})
	})

	t.Run("SignStreamStubFailing", func(t *testing.T) {
		t.Parallel()

		t.Run("fails SignAndReset with its error", func(t *testing.T) {
			t.Parallel()
			want := errors.New("SignAndReset-failing")
			s := cryptotest.NewSignStreamStub(t, cryptotest.SignStreamStubFailing(want))
			_, r1 := signStreamStubSignAndReset(t, s)
			assert.ErrorIs(t, r1, want, "SignAndReset fails with the error of SignStreamStubFailing")
		})

		t.Run("fails Write with its error", func(t *testing.T) {
			t.Parallel()
			want := errors.New("Write-failing")
			s := cryptotest.NewSignStreamStub(t, cryptotest.SignStreamStubFailing(want))
			_, err := signStreamStubWrite(t, s)
			assert.ErrorIs(t, err, want, "Write fails with the error of SignStreamStubFailing")
		})
	})

	t.Run("WithSignStreamSignAndReset", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the function of SignAndReset", func(t *testing.T) {
			t.Parallel()
			called := false
			s := cryptotest.NewSignStreamStub(t, cryptotest.WithSignStreamSignAndReset(func() ([]byte, error) {
				called = true
				var z0 []byte
				var z1 error
				return z0, z1
			}))
			_, _ = signStreamStubSignAndReset(t, s)
			assert.True(t, called, "WithSignStreamSignAndReset sets the function of SignAndReset")
		})
	})

	t.Run("WithSignStreamWrite", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the function of Write", func(t *testing.T) {
			t.Parallel()
			called := false
			s := cryptotest.NewSignStreamStub(t, cryptotest.WithSignStreamWrite(func(_ []byte) (int, error) {
				called = true
				var z0 int
				var z1 error
				return z0, z1
			}))
			_, _ = signStreamStubWrite(t, s)
			assert.True(t, called, "WithSignStreamWrite sets the function of Write")
		})
	})
}

